UPDATE calendar_events
   SET platform_account_id = #{event.platformAccountId},
       event_type          = #{event.eventType},
       title               = #{event.title},
       memo                = #{event.memo},
       start_at            = #{event.startAt},
       end_at              = #{event.endAt},
       status              = #{event.status}
 WHERE id = #{event.calendarEventId}
   AND streamer_id = #{event.streamerId}
